using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;
using Deception.Core;
using Deception.PolyModAdapter;
namespace Deception.Tests
{
 public static class IncomeTests
 {
  static int Assertions;static List<string> Cases=new();
  static void Check(bool ok,string why){Assertions++;if(!ok)throw new Exception(why);}
  static void Test(string name,Action body){try{NativeBlackmailIncomeUi.Clear();NativeBlackmail.Clear();NativeRegroupSession.Enabled=true;NativeRegroupSession.Owned.Clear();NativeGameStateEnvelope.Values.Clear();RecruitmentHooks.Registered=true;HotSeatOverlay.IsActive=false;GameManager.Viewing=true;Fault.At="";ResourceEvents.Refreshes.Clear();ResourceEvents.During=null;body();Cases.Add(name);}catch(Exception e){throw new Exception(name,e);}}
  static GameState Make(int count=1)
  {
   var s=new GameState();s.Players.AddRange(new byte[]{1,2,3,4}.Select(id=>new PlayerState{Id=id}));
   var data=new TileData{coordinates=new(2,3)};s.Map.Tiles.Add(data);var tile=new Tile{Data=data};tile.improvement=new(){Tile=tile,State=data.improvement,Owner=P(s,2)};
   var map=new MapRenderer();map.Tiles.Add(tile);MapRenderer.Current=map;GameManager.GameState=s;GameManager.Client=new(){GameState=s};GameManager.LocalPlayer=P(s,2);
   var rows=new byte[]{1,3,4}.Take(count).Select(id=>new LedgerBlackmail(id,2,2,3,4)).ToArray();var ledger=new NativeIdentityLedger(Guid.Parse("22694165-90d7-40e9-bac4-de83c2b183a8"),1,1,Array.Empty<LedgerUnit>(),Array.Empty<LedgerReceipt>(),Blackmails:rows);
   NativeGameStateEnvelope.Set(s,0,NativeIdentityLedgerCodec.Encode(WithTargets(s,ledger),0));NativeRegroupSession.Owned.Add(s);return s;
  }
  // Synthetic historical test shorthand becomes explicit supported units.
  // This is fixture construction, never production save migration.
  static NativeIdentityLedger WithTargets(GameState s,NativeIdentityLedger ledger)
  {
   var units=ledger.Units.ToList();ulong next=ledger.NextLogicalId;var rows=new List<LedgerBlackmail>();
   foreach(var mark in ledger.Blackmails??Array.Empty<LedgerBlackmail>())
   {
    if(mark.UnitId>0){rows.Add(mark);continue;}
    var body=s.Units.FirstOrDefault(u=>u.owner==mark.Victim&&u.home.X==mark.X&&u.home.Y==mark.Y);
    if(body is null){body=new(){id=(uint)(100+next),owner=mark.Victim,home=new(mark.X,mark.Y),coordinates=new(20+(int)next,20)};s.Units.Add(body);s.Map.Tiles.Add(new(){coordinates=body.coordinates,unit=body,City=false,owner=mark.Victim,Income=0});}
    var row=units.FirstOrDefault(u=>u.NativeId==body.id);
    if(row is null){row=new(next++,body.id,true,LedgerActualKind.Genuine,false,null,PaidInvestmentKind.Known,0);units.Add(row);}
    rows.Add(mark with{UnitId=row.LogicalId,LastAppliedTurn=mark.CreatedTurn});
   }
   return ledger with{NextLogicalId=next,Units=units.OrderBy(u=>u.LogicalId).ToArray(),Blackmails=rows.OrderBy(r=>r.X).ThenBy(r=>r.Y).ThenBy(r=>r.Blackmailer).ThenBy(r=>r.UnitId).ToArray()};
  }
  static PlayerState P(GameState s,byte p)=>s.Players.Single(x=>x.Id==p);
  static TileData D(GameState s)=>s.Map.Tiles[0];static City C()=>MapRenderer.Current!.Tiles[0].improvement!;
  static NativeGameStateEnvelope.Snapshot Snap(GameState s)=>NativeGameStateEnvelope.Get(s)!;
  static NativeIdentityLedger Read(GameState s)=>NativeIdentityLedgerCodec.Decode(Snap(s).Bytes(),Snap(s).Revision);
  static void Write(GameState s,NativeIdentityLedger l)=>NativeGameStateEnvelope.Set(s,Snap(s).Revision,NativeIdentityLedgerCodec.Encode(WithTargets(s,l),Snap(s).Revision));
  static string Info(GameState s,TileData? tile=null,Polytopia.Data.ImprovementData.Type type=Polytopia.Data.ImprovementData.Type.city)=>BuildingUtils.GetInfo(0,new(){type=type},(tile??D(s)).improvement,P(s,2),tile??D(s));
  static NativeBlackmailIncomeUi.Scope InfoScope(GameState s){NativeBlackmailIncomeUi.BeforeInfo(new Polytopia.Data.ImprovementData(),D(s).improvement,P(s,2),D(s),out var scope);return scope;}
  static int Work(GameState s)=>TileDataExtensions.CalculateWork(D(s),s);
  public static int Run(){try{
   Test("INCOME-001-safe-exact-hooks",()=>{var h=new HarmonyLib.Harmony();NativeBlackmailIncomeUi.Install(h);Check(h.Hooks.SequenceEqual(new[]{"BuildingUtils.GetInfo","CityStatusNameContainer.SetCity","TileDataExtensions.CalculateWork","TileDataExtensions.CalculateWork","CityStatusNameContainer.SetWork","ResourceBar.RefreshIncome","ResourceDataUtils.CalculateIncomeFor","GameManager.Update"}),"only display producers and scoped primitive queries");});
   Test("INCOME-002-city-info-net-five-to-four",()=>{var s=Make();Check(Info(s)=="Income 4","native popup formatting receives net");Check(Work(s)==5,"CalculateWork outside display remains gross");});
   Test("INCOME-003-map-label-net-five-to-four",()=>{var s=Make();var label=new CityStatusNameContainer();label.SetCity(C());Check(label.Text=="4"&&label.workContainer.gameObject.activeInHierarchy,"native star label shows net");Check(TileDataExtensions.CalculateWork(D(s),s,P(s,2),1)==5,"map producer scope fully restored");});
   Test("INCOME-004-count-all-blackmailers",()=>{var s=Make(3);Check(Info(s)=="Income 2","all three active opponents count");var label=new CityStatusNameContainer();label.SetCity(C());Check(label.Text=="2","map agrees with popup");});
   Test("INCOME-005-observer-native-authorized-city",()=>{var s=Make(2);GameManager.LocalPlayer=P(s,1);Check(Info(s)=="Income 3","visible observer sees native public net too");});
   foreach(int gross in new[]{0,1,2})Test("INCOME-006-capacity-clamped-net-"+gross,()=>{var s=Make(2);D(s).Income=gross;var label=new CityStatusNameContainer();label.SetCity(C());Check(label.Text==Math.Max(0,gross-2).ToString()&&label.workContainer.gameObject.activeInHierarchy==(gross>0),"affected zero/negative star stays visible");Check(Info(s)=="Income "+Math.Max(0,gross-2),"popup shows signed obligation");});
   Test("INCOME-007-no-mark-native-zero-stays-hidden",()=>{var s=Make(0);D(s).Income=0;var label=new CityStatusNameContainer();label.SetCity(C());Check(label.Text=="0"&&!label.workContainer.gameObject.activeInHierarchy,"ordinary native visibility remains");});
   Test("INCOME-008-native-private-or-riot-omission-not-unhidden",()=>{var s=Make();var label=new CityStatusNameContainer{OmitWork=true};label.SetCity(C());Check(!label.workContainer.gameObject.activeInHierarchy&&label.Text=="","adapter does not manufacture omitted income");});
   foreach(string guard in new[]{"hidden","unexplored","inactive-tile","detached-data","detached-render-tile","destroyed-city","changed-owner","victim-dead","blackmailer-dead","spectating","replay","unready","hotseat-cover","not-viewing","client-state","session","disabled","registry","inactive-map"})Test("INCOME-009-boundary-"+guard,()=>{var s=Make();var data=D(s);switch(guard){case"hidden":C().Tile.IsHidden=true;break;case"unexplored":data.Visible.Clear();break;case"inactive-tile":C().Tile.gameObject.SetActive(false);break;case"detached-data":data=new TileData{coordinates=data.coordinates};break;case"detached-render-tile":MapRenderer.Current!.Tiles[0].Data=new(){coordinates=D(s).coordinates};break;case"destroyed-city":data.City=false;break;case"changed-owner":data.owner=3;break;case"victim-dead":P(s,2).Alive=false;break;case"blackmailer-dead":P(s,1).Alive=false;break;case"spectating":GameManager.Client!.IsSpectating=true;break;case"replay":GameManager.Client!.IsReplay=true;break;case"unready":GameManager.Client!.IsReady=false;break;case"hotseat-cover":HotSeatOverlay.IsActive=true;break;case"not-viewing":GameManager.Viewing=false;break;case"client-state":GameManager.Client!.GameState=new();break;case"session":NativeRegroupSession.Owned.Remove(s);break;case"disabled":NativeRegroupSession.Enabled=false;break;case"registry":RecruitmentHooks.Registered=false;break;case"inactive-map":MapRenderer.Current!.gameObject.SetActive(false);break;}Check(Info(s,data)=="Income 5","invalid UI context cannot project ledger facts");});
   Test("INCOME-010-generic-tech-farm-preview-not-city",()=>{var s=Make();Check(Info(s,type:Polytopia.Data.ImprovementData.Type.farm)=="Income 5","other improvement description untouched");});
   Test("INCOME-011-info-needs-exact-native-improvement",()=>{var s=Make();NativeBlackmailIncomeUi.BeforeInfo(new Polytopia.Data.ImprovementData(),new ImprovementState(),P(s,2),D(s),out var scope);Check(Work(s)==5,"foreign state description cannot use live city mark");NativeBlackmailIncomeUi.Finished(null,scope);});
   Test("INCOME-012-map-needs-exact-native-city-and-container",()=>{var s=Make();var fake=new City{Tile=C().Tile,State=C().State,Owner=C().Owner};var label=new CityStatusNameContainer();label.SetCity(fake);Check(label.Text=="5","cloned/offscreen city no projection");});
   Test("INCOME-013-pool-reuse-removes-old-net",()=>{var s=Make();var label=new CityStatusNameContainer();label.SetCity(C());Write(s,Read(s) with{Blackmails=Array.Empty<LedgerBlackmail>()});label.SetCity(C());Check(label.Text=="5","native reset restores gross when records removed");});
   Test("INCOME-014-same-revision-replacement-refreshes",()=>{var s=Make();Check(Info(s)=="Income 4","first snapshot");Write(s,Read(s) with{Blackmails=new[]{new LedgerBlackmail(1,2,2,3,4),new LedgerBlackmail(3,2,2,3,4)}});Check(Info(s)=="Income 3"&&Snap(s).Revision==0,"same revision new snapshot counts immediately");});
   foreach(string guard in new[]{"turn","snapshot","viewer","map","generation","owner","improvement","fog","retire"})Test("INCOME-015-mid-query-invalidation-"+guard,()=>{var s=Make();var scope=InfoScope(s);switch(guard){case"turn":s.CurrentTurn++;break;case"snapshot":Write(s,Read(s));break;case"viewer":GameManager.LocalPlayer=P(s,1);break;case"map":MapRenderer.Current=new();break;case"generation":NativeBlackmailIncomeUi.Clear();break;case"owner":D(s).owner=3;break;case"improvement":D(s).improvement=new();break;case"fog":D(s).Visible.Clear();break;case"retire":NativeRegroupSession.Owned.Remove(s);break;}Check(Work(s)==5,"stale scope denied");NativeBlackmailIncomeUi.Finished(null,scope);Check(Work(s)==5,"expired scope cannot revive");});
   Test("INCOME-016-nested-invalid-scope-fences-outer",()=>{var s=Make();var outer=InfoScope(s);Check(Work(s)==4,"outer valid");NativeBlackmailIncomeUi.BeforeInfo(new Polytopia.Data.ImprovementData{type=Polytopia.Data.ImprovementData.Type.farm},D(s).improvement,P(s,2),D(s),out var inner);Check(Work(s)==5,"nested unrelated producer cannot borrow outer entitlement");NativeBlackmailIncomeUi.Finished(null,inner);Check(Work(s)==4,"outer restored once");NativeBlackmailIncomeUi.Finished(null,outer);Check(Work(s)==5,"query state fully reset");});
   Test("INCOME-017-exception-and-duplicate-finalizer-cleanup",()=>{var s=Make();var scope=InfoScope(s);var e=new Exception("native formatter");Check(ReferenceEquals(e,NativeBlackmailIncomeUi.Finished(e,scope))&&Work(s)==5,"native exception preserved and scope unwound");NativeBlackmailIncomeUi.Finished(null,scope);Check(Work(s)==5,"duplicate finalizer inert");});
   Test("INCOME-018-unrelated-tile-and-state-unchanged-in-scope",()=>{var s=Make();var scope=InfoScope(s);Check(TileDataExtensions.CalculateWork(new TileData(),s)==5&&TileDataExtensions.CalculateWork(D(s),new GameState())==5,"exact query target/state required");Check(TileDataExtensions.CalculateWork(D(s),s,P(s,2),1)==5,"map overload cannot borrow info scope");NativeBlackmailIncomeUi.Finished(null,scope);});
   Test("INCOME-019-work-widget-requires-projected-call",()=>{var s=Make();var label=new CityStatusNameContainer();NativeBlackmailIncomeUi.BeforeCity(label,C(),out var scope);label.city=C();label.SetWork(0);Check(!label.workContainer.gameObject.activeInHierarchy,"unrelated SetWork zero not forcibly visible");NativeBlackmailIncomeUi.Finished(null,scope);});
   Test("INCOME-020-info-and-map-do-not-mutate-income-or-money",()=>{var s=Make(2);var snap=Snap(s);for(int i=0;i<3;i++){Info(s);new CityStatusNameContainer().SetCity(C());}Check(D(s).Income==5&&s.Players.All(p=>p.Currency==20)&&ReferenceEquals(snap,Snap(s)),"display changes neither native values nor ledger");var action=new IncreaseCurrencyAction{PlayerId=2,Amount=Work(s)};action.Execute(s);Check(P(s,2).Currency==25,"native income still grants full five");s.CurrentPlayer=2;var marker=new EndCommandAction();s.ActionStack.Add(marker);NativeBlackmail.BeforeSettlement(marker,s,out var scope);NativeBlackmail.AfterNative(true,scope);Check(NativeBlackmail.Finished(null,scope) is null&&P(s,2).Currency==23&&P(s,1).Currency==20&&P(s,3).Currency==20,"victim settlement deducts two once without out-of-turn credit");s.CurrentPlayer=1;s.CurrentTurn++;var credit=new EndCommandAction();s.ActionStack.Add(credit);NativeBlackmail.BeforeSettlement(credit,s,out var incoming);NativeBlackmail.AfterNative(true,incoming);Check(NativeBlackmail.Finished(null,incoming) is null&&P(s,1).Currency==21&&P(s,2).Currency==23&&P(s,3).Currency==20,"blackmailer receives its income on its own next turn, no UI double credit");});
   Test("INCOME-021-skipped-native-query-not-projected",()=>{var s=Make();var scope=InfoScope(s);int value=5;NativeBlackmailIncomeUi.InfoWork(D(s),s,false,ref value);Check(value==5,"another prefix skipping native preserves its result");NativeBlackmailIncomeUi.Finished(null,scope);});
   Test("INCOME-022-out-of-order-finalizers-never-revive-closed-scope",()=>{var s=Make();var outer=InfoScope(s);var inner=InfoScope(s);NativeBlackmailIncomeUi.Finished(null,outer);Check(Work(s)==4,"current inner survives late outer completion");NativeBlackmailIncomeUi.Finished(null,inner);Check(Work(s)==5,"closed outer cannot become current again");});

   Test("INCOME-023-header-victim-net-and-native-query-unchanged",()=>{var s=Make(2);var snap=Snap(s);var bar=new ResourceBar();bar.RefreshIncome(2);Check(bar.Income==3,"victim header shows five minus two");Check(ResourceDataUtils.CalculateIncomeFor(s,2)==5&&Work(s)==5&&ReferenceEquals(snap,Snap(s))&&P(s,2).Currency==20,"direct native queries and actual state stay unchanged");});
   Test("INCOME-024-header-blackmailer-incoming-own-income",()=>{var s=Make();GameManager.LocalPlayer=P(s,1);var bar=new ResourceBar();bar.RefreshIncome(1);Check(bar.Income==1,"actor header forecasts incoming one");Check(ResourceDataUtils.CalculateIncomeFor(s,1)==0&&P(s,1).Currency==20,"not paid by display");});
   Test("INCOME-025-header-clamped-net-and-inactive-rows",()=>{var s=Make(3);D(s).Income=1;var bar=new ResourceBar();bar.RefreshIncome(2);Check(bar.Income==0,"debits cannot exceed supporting city capacity");D(s).owner=4;bar.RefreshIncome(2);Check(bar.Income==0,"capture removes debit projection immediately");});
   Test("INCOME-026-header-other-player-inactive-ui-no-projection",()=>{var s=Make();var bar=new ResourceBar();bar.RefreshIncome(1);Check(bar.Income==0,"foreign player query cannot borrow viewer header");bar.gameObject.SetActive(false);bar.RefreshIncome(2);Check(bar.Income==5,"inactive bar cannot project");});
   Test("INCOME-027-header-both-income-directions",()=>{var s=Make();var second=new TileData{coordinates=new(3,3),owner=3};s.Map.Tiles.Add(second);Write(s,Read(s)with{Blackmails=new[]{new LedgerBlackmail(1,2,2,3,4),new LedgerBlackmail(2,3,3,3,4)}});var bar=new ResourceBar();bar.RefreshIncome(2);Check(bar.Income==5,"own debit and outgoing income sum once");});
   Test("INCOME-028-header-snapshot-context-lifetime",()=>{var s=Make();var bar=new ResourceBar();NativeBlackmailIncomeUi.BeforeHeader(bar,2,out var scope);Check(ResourceDataUtils.CalculateIncomeFor(s,2)==4,"live header scope");Write(s,Read(s));Check(ResourceDataUtils.CalculateIncomeFor(s,2)==5,"snapshot invalidates stale projection");var e=new Exception("native header");Check(ReferenceEquals(e,NativeBlackmailIncomeUi.HeaderFinished(e,scope)),"native exception retained");});
   Test("INCOME-029-header-invalid-nested-and-clear",()=>{var s=Make();var bar=new ResourceBar();NativeBlackmailIncomeUi.BeforeHeader(bar,2,out var outer);NativeBlackmailIncomeUi.BeforeHeader(bar,1,out var inner);Check(ResourceDataUtils.CalculateIncomeFor(s,2)==5,"foreign nested header fences outer");NativeBlackmailIncomeUi.HeaderFinished(null,inner);Check(ResourceDataUtils.CalculateIncomeFor(s,2)==4,"outer restored");NativeBlackmailIncomeUi.Clear();NativeBlackmailIncomeUi.HeaderFinished(null,outer);Check(ResourceDataUtils.CalculateIncomeFor(s,2)==5,"cleared scope never revived");});
   Test("INCOME-030-header-skipped-query-and-wrong-state",()=>{var s=Make();NativeBlackmailIncomeUi.BeforeHeader(new ResourceBar(),2,out var scope);int value=5;NativeBlackmailIncomeUi.HeaderIncome(s,2,false,ref value);Check(value==5&&ResourceDataUtils.CalculateIncomeFor(new(),2)==0,"skipped and unrelated native result untouched");NativeBlackmailIncomeUi.HeaderFinished(null,scope);});
   Test("INCOME-031-header-and-city-producers-fence-each-other",()=>{var s=Make();var bar=new CityStatusNameContainer();NativeBlackmailIncomeUi.BeforeCity(bar,C(),out var city);bar.city=C();NativeBlackmailIncomeUi.BeforeHeader(new ResourceBar(),2,out var header);Check(TileDataExtensions.CalculateWork(D(s),s,P(s,2),1)==5,"header underlying work cannot borrow older city projection");Check(ResourceDataUtils.CalculateIncomeFor(s,2)==4,"header nets only once");var inner=InfoScope(s);Check(ResourceDataUtils.CalculateIncomeFor(s,2)==5&&Work(s)==4,"newer city context fences older header");NativeBlackmailIncomeUi.Finished(null,inner);NativeBlackmailIncomeUi.HeaderFinished(null,header);Check(TileDataExtensions.CalculateWork(D(s),s,P(s,2),1)==4,"city context restored after header");NativeBlackmailIncomeUi.Finished(null,city);});
   Test("INCOME-032-header-requires-exact-data-map",()=>{var s=Make();NativeBlackmailIncomeUi.BeforeHeader(new ResourceBar(),2,out var scope);s.Map=new();int value=5;NativeBlackmailIncomeUi.HeaderIncome(s,2,true,ref value);Check(value==5,"state map replacement invalidates header even with retained renderer");NativeBlackmailIncomeUi.HeaderFinished(null,scope);});
   Test("INCOME-033-header-refresh-on-setup-and-clear",()=>{var s=Make(0);NativeBlackmailIncomeUi.Tick();Write(s,Read(s)with{Blackmails=new[]{new LedgerBlackmail(1,2,2,3,4)}});NativeBlackmailIncomeUi.Tick();Check(ResourceEvents.Refreshes.SequenceEqual(new byte[]{2,2}),"setup triggers current victim header event immediately");Write(s,Read(s)with{Blackmails=Array.Empty<LedgerBlackmail>()});NativeBlackmailIncomeUi.Tick();Check(ResourceEvents.Refreshes.Count==3,"peace/capture removal refreshes forecast");});
   Test("INCOME-034-header-refresh-idle-cache-and-same-net",()=>{var s=Make();NativeBlackmailIncomeUi.Tick();int reads=Snap(s).Reads;for(int i=0;i<100;i++)NativeBlackmailIncomeUi.Tick();Check(ResourceEvents.Refreshes.Count==1&&Snap(s).Reads==reads,"idle frames do not scan/redecode ledger or re-emit events");Write(s,Read(s));NativeBlackmailIncomeUi.Tick();Check(ResourceEvents.Refreshes.Count==1,"same net on new snapshot does not emit");GameManager.LocalPlayer=P(s,1);NativeBlackmailIncomeUi.Tick();Check(ResourceEvents.Refreshes.Last()==1&&ResourceEvents.Refreshes.Count==2,"new hotseat/viewer receives its own forecast update");});
   Test("INCOME-035-header-refresh-defers-recap-and-reentry",()=>{var s=Make();GameManager.Client!.IsRecap=true;NativeBlackmailIncomeUi.Tick();GameManager.Client.IsRecap=false;GameManager.Client.ActionManager.IsProcessing=true;NativeBlackmailIncomeUi.Tick();Check(ResourceEvents.Refreshes.Count==0,"recap and processing stay native");GameManager.Client.ActionManager.IsProcessing=false;ResourceEvents.During=NativeBlackmailIncomeUi.Tick;NativeBlackmailIncomeUi.Tick();Check(ResourceEvents.Refreshes.Count==1,"native event reentry cannot recurse");});
   Test("INCOME-036-header-event-error-retries-and-clear-invalidates",()=>{Make();Fault.At="income-event";NativeBlackmailIncomeUi.Tick();NativeBlackmailIncomeUi.Tick();Check(ResourceEvents.Refreshes.Count==1,"event failure remains retryable");ResourceEvents.During=NativeBlackmailIncomeUi.Clear;NativeBlackmailIncomeUi.Clear();NativeBlackmailIncomeUi.Tick();ResourceEvents.During=null;NativeBlackmailIncomeUi.Tick();Check(ResourceEvents.Refreshes.Count==3,"late event cannot restore a cleared stamp");});
   Test("INCOME-037-stacked-layers-reduce-city-and-header",()=>{var s=Make();Write(s,Read(s)with{Blackmails=Read(s).Blackmails!.Select(r=>r with{Layers=3}).ToArray()});Check(Info(s)=="Income 2","one target has three effective charges");var label=new CityStatusNameContainer();label.SetCity(C());Check(label.Text=="2","map city count equals popup");var header=new ResourceBar();header.RefreshIncome(2);Check(header.Income==2,"victim header sums layers");GameManager.LocalPlayer=P(s,1);header.RefreshIncome(1);Check(header.Income==3,"actor header sums layers");});
   Test("INCOME-038-home-production-change-caps-forecasts",()=>{var s=Make();Write(s,Read(s)with{Blackmails=Read(s).Blackmails!.Select(r=>r with{Layers=3}).ToArray()});NativeBlackmailIncomeUi.Tick();D(s).Income=1;s.CurrentCommand++;NativeBlackmailIncomeUi.Tick();Check(ResourceEvents.Refreshes.Count==2&&Info(s)=="Income 0","native command capacity drop must invalidate forecast");GameManager.LocalPlayer=P(s,1);var header=new ResourceBar();header.RefreshIncome(1);Check(header.Income==1,"no manufactured stars when capacity falls");});
   Test("INCOME-039-gross-read-inside-city-scope-is-not-projected",()=>{var s=Make();var scope=InfoScope(s);Check(Work(s)==4,"ordinary producer projected");Check(NativeBlackmail.GrossIncome(s,D(s))==5,"capacity query cannot recursively deduct display value");NativeBlackmailIncomeUi.Finished(null,scope);});
   Console.WriteLine(JsonSerializer.Serialize(new{passed=true,cases=Cases.Count,assertions=Assertions,tests=Cases,scope="Real income UI projection and settlement against synthetic native boundary; no gameplay claim"}));return 0;
  }catch(Exception e){Console.WriteLine(JsonSerializer.Serialize(new{passed=false,cases=Cases.Count,assertions=Assertions,error=e.ToString()}));return 1;}}
 }
}
